1	import { useMemo, useState } from 'react';
2	import {
3	  BarChart,
4	  Bar,
5	  XAxis,
6	  YAxis,
7	  CartesianGrid,
8	  Tooltip,
9	  ResponsiveContainer,
10	  PieChart,
11	  Pie,
12	  Cell,
13	  AreaChart,
14	  Area,
15	} from 'recharts';
16	import {
17	  TrendingUp,
18	  Package,
19	  Store,
20	  CalendarIcon,
21	  Download,
22	  Wallet,
23	  AlertCircle,
24	  User,
25	  Tag,
26	  FileText,
27	} from 'lucide-react';
28	import {
29	  format,
30	  parseISO,
31	  startOfYear,
32	  startOfMonth,
33	  subDays,
34	  isValid,
35	  isEqual,
36	  differenceInDays,
37	} from 'date-fns';
38	import { ptBR } from 'date-fns/locale';
39	import { Button } from '@/shared/ui/button';
40	import { Popover, PopoverContent, PopoverTrigger } from '@/shared/ui/popover';
41	import { Calendar } from '@/shared/ui/calendar';
42	import { DateRange } from 'react-day-picker';
43	import { cn } from '@/shared/lib/utils';
44	import * as XLSX from 'xlsx';
45	import { toast } from 'sonner';
46	import {
47	  Dialog,
48	  DialogContent,
49	  DialogDescription,
50	  DialogHeader,
51	  DialogTitle,
52	} from '@/shared/ui/dialog';
53	import {
54	  CATEGORIAS_NF,
55	  normalizeCategoria,
56	  type CategoriaNF,
57	} from '@/features/notas-fiscais/lib/categorias';
58	
59	// Colors (matching Momma Palette)
60	const KPICOLORS = {
61	  red: 'from-[#ef4444] to-[#b91c1c] text-white',
62	  orange: 'from-[#f97316] to-[#c2410c] text-white',
63	  gold: 'from-[#C5A065] to-[#B08D55] text-white',
64	  green: 'from-[#57715B] to-[#4A614E] text-white',
65	  dark: 'from-[#2D362E] to-[#1A1A1A] text-[#E6DCCF]',
66	  blue: 'from-[#3b82f6] to-[#1d4ed8] text-white',
67	  purple: 'from-[#8b5cf6] to-[#6d28d9] text-white',
68	  teal: 'from-[#0d9488] to-[#0f766e] text-white',
69	};
70	
71	const CHART_COLORS = [
72	  '#C5A065',
73	  '#57715B',
74	  '#8B4513',
75	  '#2D362E',
76	  '#ef4444',
77	  '#3b82f6',
78	  '#8b5cf6',
79	];
80	
81	interface InvoiceItem {
82	  id: number;
83	  numero_nota: string;
84	  fornecedor: string;
85	  data_nota: string | null;
86	  created_at: string;
87	  valor_total: number;
88	  status: string;
89	  itens_nota_fiscal?: {
90	    id: number;
91	    nome_produto: string;
92	    quantidade: number;
93	    valor_unitario: number;
94	    subtotal: number;
95	    categoria?: string;
96	  }[];
97	}
98	
99	interface InvoiceAnalyticsDashboardProps {
100	  invoices: InvoiceItem[];
101	}
102	
103	export function InvoiceAnalyticsDashboard({
104	  invoices,
105	}: InvoiceAnalyticsDashboardProps) {
106	  const today = new Date();
107	  const defaultStart = startOfMonth(today);
108	
109	  // State for Date Range Filter
110	  const [dateRange, setDateRange] = useState<DateRange | undefined>({
111	    from: defaultStart,
112	    to: today,
113	  });
114	
115	  const [selectedMetric, setSelectedMetric] = useState<string | null>(null);
116	  const [drilldownCategory, setDrilldownCategory] = useState<CategoriaNF | null>(null);
117	
118	  // --- Filter Logic ---
119	  const filteredInvoices = useMemo(() => {
120	    if (!dateRange?.from) return invoices;
121	
122	    return invoices.filter((invoice) => {
123	      const dateStr = invoice.data_nota || invoice.created_at;
124	      if (!dateStr) return false;
125	      const date = parseISO(dateStr);
126	      if (!isValid(date)) return false;
127	
128	      const from = dateRange.from as Date;
129	      const to = dateRange.to || dateRange.from || new Date();
130	
131	      const target = date.getTime();
132	      const startStr = new Date(from).setHours(0, 0, 0, 0);
133	      const endStr = new Date(to).setHours(23, 59, 59, 999);
134	
135	      return target >= startStr && target <= endStr;
136	    });
137	  }, [invoices, dateRange]);
138	
139	  // --- Analytics Logic ---
140	  const analytics = useMemo(() => {
141	    const totalRecords = filteredInvoices.length;
142	    const totalValue = filteredInvoices.reduce(
143	      (acc, curr) => acc + (Number(curr.valor_total) || 0),
144	      0,
145	    );
146	
147	    // Daily Averages
148	    const daysDiff =
149	      dateRange?.from && dateRange?.to
150	        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1)
151	        : 30;
152	
153	    const avgDailyVal = totalValue / daysDiff;
154	    const avgTicket = totalRecords > 0 ? totalValue / totalRecords : 0;
155	
156	    // Grouping Logic
157	    const isDailyGroup = daysDiff < 60;
158	
159	    const bySupplierValue: Record<string, number> = {};
160	    const supplierDisplayNames: Record<string, string> = {};
161	    const byCategoryValue: Record<string, number> = {};
162	    const byProductValue: Record<string, number> = {};
163	    const byCategoryProducts: Record<string, Record<string, { qtd: number; valor: number; fornecedores: Set<string> }>> = {};
164	    const byTime: Record<
165	      string,
166	      { date: string; value: number; count: number }
167	    > = {};
168	
169	    // Flatten items for product/category analysis
170	    let totalItems = 0;
171	
172	    filteredInvoices.forEach((invoice) => {
173	      const dateStr = invoice.data_nota || invoice.created_at;
174	      const date = dateStr ? parseISO(dateStr) : new Date();
175	      const timeKey = isDailyGroup
176	        ? format(date, 'yyyy-MM-dd')
177	        : format(date, 'yyyy-MM');
178	
179	      const val = Number(invoice.valor_total) || 0;
180	      const supplierRaw = (invoice.fornecedor || 'Outros').trim();
181	      const supplierKey = supplierRaw.toLowerCase();
182	
183	      // Time grouping
184	      if (!byTime[timeKey])
185	        byTime[timeKey] = { date: timeKey, value: 0, count: 0 };
186	      byTime[timeKey].value += val;
187	      byTime[timeKey].count += 1;
188	
189	      // Supplier grouping (case-insensitive)
190	      if (!bySupplierValue[supplierKey]) bySupplierValue[supplierKey] = 0;
191	      bySupplierValue[supplierKey] += val;
192	      // Guardar nome display (primeira ocorrência)
193	      if (!supplierDisplayNames[supplierKey]) supplierDisplayNames[supplierKey] = supplierRaw;
194	
195	      // Items grouping
196	      if (invoice.itens_nota_fiscal && invoice.itens_nota_fiscal.length > 0) {
197	        invoice.itens_nota_fiscal.forEach((item) => {
198	          totalItems++;
199	          const itemVal = Number(item.subtotal) || 0;
200	          const prod = item.nome_produto || 'Produto Desconhecido';
201	          const cat = normalizeCategoria(item.categoria);
202	
203	          byProductValue[prod] = (byProductValue[prod] || 0) + itemVal;
204	          byCategoryValue[cat] = (byCategoryValue[cat] || 0) + itemVal;
205	
206	          if (!byCategoryProducts[cat]) byCategoryProducts[cat] = {};
207	          if (!byCategoryProducts[cat][prod]) {
208	            byCategoryProducts[cat][prod] = { qtd: 0, valor: 0, fornecedores: new Set() };
209	          }
210	          byCategoryProducts[cat][prod].qtd += Number(item.quantidade) || 0;
211	          byCategoryProducts[cat][prod].valor += itemVal;
212	          if (invoice.fornecedor) {
213	            byCategoryProducts[cat][prod].fornecedores.add(invoice.fornecedor);
214	          }
215	        });
216	      } else {
217	        // If no items, attribute entire value to "Geral" or similar if needed,
218	        // but let's just track supplier/time for the main invoice.
219	      }
220	    });
221	
222	    // Computed Stats
223	    const topSupplierEntry = Object.entries(bySupplierValue)
224	      .map(([key, val]) => [supplierDisplayNames[key] || key, val] as [string, number])
225	      .sort((a, b) => b[1] - a[1])[0];
226	    const topCategoryEntry = Object.entries(byCategoryValue).sort(
227	      (a, b) => b[1] - a[1],
228	    )[0];
229	    const topProductEntry = Object.entries(byProductValue).sort(
230	      (a, b) => b[1] - a[1],
231	    )[0];
232	
233	    // Chart Data
234	    const formatDecimal = (num: number) => Number(num.toFixed(2));
235	
236	    const supplierChartData = Object.entries(bySupplierValue)
237	      .map(([key, value]) => ({ name: supplierDisplayNames[key] || key, value: formatDecimal(value) }))
238	      .sort((a, b) => b.value - a.value)
239	      .slice(0, 10);
240	
241	    const categoryChartData = Object.entries(byCategoryValue)
242	      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
243	      .sort((a, b) => b.value - a.value);
244	
245	    const productChartData = Object.entries(byProductValue)
246	      .map(([name, value]) => ({ name, value: formatDecimal(value) }))
247	      .sort((a, b) => b.value - a.value)
248	      .slice(0, 10);
249	
250	    const timeData = Object.values(byTime)
251	      .sort((a, b) => a.date.localeCompare(b.date))
252	      .map((item) => ({
253	        ...item,
254	        value: formatDecimal(item.value),
255	        name: isDailyGroup
256	          ? format(parseISO(item.date), 'dd/MM')
257	          : format(parseISO(item.date), 'MMM/yy', { locale: ptBR }),
258	      }));
259	
260	    const detailedList = filteredInvoices
261	      .map((inv) => ({
262	        ...inv,
263	        val: Number(inv.valor_total) || 0,
264	        date: inv.data_nota || inv.created_at,
265	      }))
266	      .sort((a, b) => b.val - a.val);
267	
268	    return {
269	      totalRecords,
270	      totalValue: formatDecimal(totalValue),
271	      avgDailyVal: formatDecimal(avgDailyVal),
272	      avgTicket: formatDecimal(avgTicket),
273	      totalItems,
274	
275	      topSupplierName: topSupplierEntry ? topSupplierEntry[0] : '-',
276	      topSupplierAmount: topSupplierEntry
277	        ? formatDecimal(topSupplierEntry[1])
278	        : 0,
279	
280	      topCategoryName: topCategoryEntry ? topCategoryEntry[0] : '-',
281	      topCategoryAmount: topCategoryEntry
282	        ? formatDecimal(topCategoryEntry[1])
283	        : 0,
284	
285	      topProductName: topProductEntry ? topProductEntry[0] : '-',
286	      topProductAmount: topProductEntry ? formatDecimal(topProductEntry[1]) : 0,
287	
288	      supplierChartData,
289	      categoryChartData,
290	      productChartData,
291	      timeData,
292	      detailedList,
293	      byCategoryProducts,
294	    };
295	  }, [filteredInvoices, dateRange]);
296	
297	  const drilldownSummary = useMemo(() => {
298	    if (!drilldownCategory) return { top: [], totalProdutos: 0, totalValor: 0 };
299	    const map = analytics.byCategoryProducts[drilldownCategory] || {};
300	    const all = Object.entries(map)
301	      .map(([nome_produto, d]) => ({
302	        nome_produto,
303	        qtd: d.qtd,
304	        valor: Number(d.valor.toFixed(2)),
305	        fornecedores: Array.from(d.fornecedores).join(', '),
306	      }))
307	      .sort((a, b) => b.valor - a.valor);
308	    return {
309	      top: all.slice(0, 10),
310	      totalProdutos: all.length,
311	      totalValor: all.reduce((acc, p) => acc + p.valor, 0),
312	    };
313	  }, [drilldownCategory, analytics.byCategoryProducts]);
314	
315	  // --- Export Logic ---
316	  const handleExport = () => {
317	    if (!analytics.detailedList.length) {
318	      toast.error('Sem dados para exportar.');
319	      return;
320	    }
321	
322	    const header = [
323	      'Data Emissão',
324	      'Fornecedor',
325	      'Número Nota',
326	      'Valor Total (R$)',
327	      'Status',
328	    ];
329	    const rows = analytics.detailedList.map((item) => [
330	      item.date ? format(parseISO(item.date), 'dd/MM/yyyy') : '-',
331	      item.fornecedor,
332	      item.numero_nota,
333	      item.val.toFixed(2),
334	      item.status,
335	    ]);
336	
337	    const wb = XLSX.utils.book_new();
338	    const ws = XLSX.utils.aoa_to_sheet([header, ...rows]);
339	    XLSX.utils.book_append_sheet(wb, ws, 'Notas Filtradas');
340	    XLSX.writeFile(
341	      wb,
342	      `Relatorio_Analise_Notas_${format(new Date(), 'yyyyMMdd_HHmm')}.xlsx`,
343	    );
344	    toast.success('Relatório gerado com sucesso!');
345	  };
346	
347	  // --- Modal/Detail Content for Clicked KPI ---
348	  const renderDetailContent = () => {
349	    if (!analytics || !selectedMetric) return null;
350	
351	    switch (selectedMetric) {
352	      case 'Total Gasto':
353	      case 'Evolução':
354	        return (
355	          <div className="h-80">
356	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
357	              Evolução do Gasto
358	            </h4>
359	            <ResponsiveContainer width="100%" height="100%">
360	              <AreaChart data={analytics.timeData}>
361	                <defs>
362	                  <linearGradient id="colorVal" x1="0" y1="0" x2="0" y2="1">
363	                    <stop offset="5%" stopColor="#C5A065" stopOpacity={0.8} />
364	                    <stop offset="95%" stopColor="#C5A065" stopOpacity={0} />
365	                  </linearGradient>
366	                </defs>
367	                <CartesianGrid strokeDasharray="3 3" vertical={false} />
368	                <XAxis dataKey="name" tick={{ fontSize: 10 }} />
369	                <YAxis tick={{ fontSize: 10 }} />
370	                <Tooltip
371	                  formatter={(value: number) =>
372	                    new Intl.NumberFormat('pt-BR', {
373	                      style: 'currency',
374	                      currency: 'BRL',
375	                    }).format(value)
376	                  }
377	                />
378	                <Area
379	                  type="monotone"
380	                  dataKey="value"
381	                  stroke="#C5A065"
382	                  fill="url(#colorVal)"
383	                  name="Valor (R$)"
384	                />
385	              </AreaChart>
386	            </ResponsiveContainer>
387	          </div>
388	        );
389	      case 'Top Fornecedor':
390	        return (
391	          <div className="h-80">
392	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
393	              Top 10 Fornecedores (Valor)
394	            </h4>
395	            <ResponsiveContainer width="100%" height="100%">
396	              <BarChart data={analytics.supplierChartData} layout="vertical">
397	                <CartesianGrid
398	                  strokeDasharray="3 3"
399	                  horizontal={true}
400	                  vertical={false}
401	                />
402	                <XAxis type="number" hide />
403	                <YAxis
404	                  dataKey="name"
405	                  type="category"
406	                  width={150}
407	                  tickFormatter={(value) =>
408	                    value.length > 20 ? `${value.substring(0, 20)}...` : value
409	                  }
410	                  tick={{ fontSize: 11 }}
411	                />
412	                <Tooltip
413	                  formatter={(value: number) =>
414	                    new Intl.NumberFormat('pt-BR', {
415	                      style: 'currency',
416	                      currency: 'BRL',
417	                    }).format(value)
418	                  }
419	                />
420	                <Bar
421	                  dataKey="value"
422	                  fill="#57715B"
423	                  radius={[0, 4, 4, 0]}
424	                  barSize={24}
425	                  name="Total (R$)"
426	                />
427	              </BarChart>
428	            </ResponsiveContainer>
429	          </div>
430	        );
431	      case 'Top Categoria': {
432	        const totalCategoria = analytics.categoryChartData.reduce((acc, c) => acc + c.value, 0);
433	        return (
434	          <div>
435	            <h4 className="text-sm font-bold text-center mb-1 text-muted-foreground">
436	              Gastos por Categoria
437	            </h4>
438	            <p className="text-xs text-center text-muted-foreground mb-3">
439	              Clique em uma categoria na lista para ver os produtos.
440	            </p>
441	            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 items-center">
442	              <div className="h-72">
443	                <ResponsiveContainer width="100%" height="100%">
444	                  <PieChart>
445	                    <Pie
446	                      data={analytics.categoryChartData}
447	                      dataKey="value"
448	                      nameKey="name"
449	                      cx="50%"
450	                      cy="50%"
451	                      outerRadius={90}
452	                      onClick={(entry: any) => {
453	                        const name = entry?.name as string | undefined;
454	                        if (name && (CATEGORIAS_NF as readonly string[]).includes(name)) {
455	                          setDrilldownCategory(name as CategoriaNF);
456	                        }
457	                      }}
458	                      style={{ cursor: 'pointer' }}
459	                    >
460	                      {analytics.categoryChartData.map((_, index) => (
461	                        <Cell
462	                          key={`cell-${index}`}
463	                          fill={CHART_COLORS[index % CHART_COLORS.length]}
464	                        />
465	                      ))}
466	                    </Pie>
467	                    <Tooltip
468	                      formatter={(value: number) =>
469	                        new Intl.NumberFormat('pt-BR', {
470	                          style: 'currency',
471	                          currency: 'BRL',
472	                        }).format(value)
473	                      }
474	                    />
475	                  </PieChart>
476	                </ResponsiveContainer>
477	              </div>
478	
479	              <div className="space-y-1 max-h-72 overflow-y-auto pr-2">
480	                {analytics.categoryChartData.map((c, index) => {
481	                  const pct = totalCategoria > 0 ? (c.value / totalCategoria) * 100 : 0;
482	                  const color = CHART_COLORS[index % CHART_COLORS.length];
483	                  const isCanonica = (CATEGORIAS_NF as readonly string[]).includes(c.name);
484	                  return (
485	                    <button
486	                      key={c.name}
487	                      type="button"
488	                      onClick={() => {
489	                        if (isCanonica) setDrilldownCategory(c.name as CategoriaNF);
490	                      }}
491	                      disabled={!isCanonica}
492	                      className="w-full flex items-center gap-2 p-2 rounded-lg hover:bg-[#57715B]/10 transition-colors text-left group disabled:opacity-60 disabled:cursor-not-allowed"
493	                    >
494	                      <span
495	                        className="w-3 h-3 rounded-sm shrink-0"
496	                        style={{ backgroundColor: color }}
497	                      />
498	                      <div className="flex-1 min-w-0">
499	                        <div className="flex items-baseline justify-between gap-2">
500	                          <span className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF] truncate group-hover:text-[#57715B]">
501	                            {c.name}
502	                          </span>
503	                          <span className="text-xs font-semibold tabular-nums text-[#57715B]">
504	                            {new Intl.NumberFormat('pt-BR', {
505	                              style: 'currency',
506	                              currency: 'BRL',
507	                              maximumFractionDigits: 0,
508	                            }).format(c.value)}
509	                          </span>
510	                        </div>
511	                        <div className="flex items-center gap-2">
512	                          <div className="flex-1 h-1 bg-[#57715B]/10 rounded-full overflow-hidden">
513	                            <div
514	                              className="h-full rounded-full"
515	                              style={{ width: `${pct}%`, backgroundColor: color }}
516	                            />
517	                          </div>
518	                          <span className="text-[10px] tabular-nums text-muted-foreground w-10 text-right">
519	                            {pct.toFixed(1)}%
520	                          </span>
521	                        </div>
522	                      </div>
523	                    </button>
524	                  );
525	                })}
526	                {analytics.categoryChartData.length === 0 && (
527	                  <p className="text-center text-sm text-muted-foreground py-6">
528	                    Nenhuma categoria no período.
529	                  </p>
530	                )}
531	              </div>
532	            </div>
533	          </div>
534	        );
535	      }
536	      case 'Top Produto':
537	        return (
538	          <div className="h-80">
539	            <h4 className="text-sm font-bold text-center mb-4 text-muted-foreground">
540	              Top 10 Produtos (Custo)
541	            </h4>
542	            <ResponsiveContainer width="100%" height="100%">
543	              <BarChart data={analytics.productChartData} layout="vertical">
544	                <CartesianGrid
545	                  strokeDasharray="3 3"
546	                  horizontal={true}
547	                  vertical={false}
548	                />
549	                <XAxis type="number" hide />
550	                <YAxis
551	                  dataKey="name"
552	                  type="category"
553	                  width={120}
554	                  tick={{ fontSize: 10 }}
555	                />
556	                <Tooltip
557	                  formatter={(value: number) =>
558	                    new Intl.NumberFormat('pt-BR', {
559	                      style: 'currency',
560	                      currency: 'BRL',
561	                    }).format(value)
562	                  }
563	                />
564	                <Bar
565	                  dataKey="value"
566	                  fill="#8B4513"
567	                  radius={[0, 4, 4, 0]}
568	                  barSize={24}
569	                  name="Custo (R$)"
570	                />
571	              </BarChart>
572	            </ResponsiveContainer>
573	          </div>
574	        );
575	      case 'Ticket Médio':
576	        return (
577	          <div className="flex flex-col items-center justify-center h-64 text-center p-4">
578	            <Wallet className="w-16 h-16 text-[#C5A065] mb-4 opacity-50" />
579	            <h3 className="text-2xl font-bold text-[#2D362E]">Ticket Médio</h3>
580	            <p className="text-4xl font-extrabold text-[#C5A065] my-2">
581	              {new Intl.NumberFormat('pt-BR', {
582	                style: 'currency',
583	                currency: 'BRL',
584	              }).format(analytics.avgTicket)}
585	            </p>
586	            <p className="text-sm text-muted-foreground">
587	              Média do valor por nota fiscal processada no período.
588	            </p>
589	          </div>
590	        );
591	      default:
592	        return (
593	          <div className="p-4 text-center">
594	            Selecione uma métrica para ver detalhes.
595	          </div>
596	        );
597	    }
598	  };
599	
600	  const isRangeActive = (start: Date, end: Date) => {
601	    if (!dateRange?.from || !dateRange?.to) return false;
602	    return isEqual(start, dateRange.from) && isEqual(end, dateRange.to);
603	  };
604	
605	  return (
606	    <div className="space-y-6 pb-20 animate-in fade-in duration-500">
607	      {/* Filter Header */}
608	      <div className="flex flex-col md:flex-row items-center justify-between gap-4 bg-white/50 dark:bg-black/20 p-2 rounded-2xl backdrop-blur-sm border border-[#57715B]/10">
